using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputSlurProof {static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[0]),common=File.ReadAllBytes(a[1]),tokens=File.ReadAllBytes(a[2]),prefs=File.ReadAllBytes(a[3]),after=File.ReadAllBytes(a[4]);int count=BitConverter.ToInt16(ds,0x8798),boundary=BitConverter.ToInt16(ds,0x8792);var map=new int[boundary];var stems=new int[boundary];for(int i=1;i<boundary;i++){map[i]=BitConverter.ToInt16(common,0x2b5a+i*2);stems[i]=BitConverter.ToInt16(common,0x2a2e+i*2);}var rows=new List<float[]>();for(int i=0;i<count;i++){var p=new float[15];Buffer.BlockCopy(common,i*60,p,0,60);rows.Add(p);}float begin=BitConverter.ToSingle(ds,0x8144),end=BitConverter.ToSingle(ds,0x8148);var result=rows;for(int token=0;token<BitConverter.ToInt16(tokens,0);token+=2){var e=InputEndpointProjection.Decode(BitConverter.ToSingle(tokens,2+token*4),BitConverter.ToSingle(tokens,6+token*4),5,result,map,stems,begin,end);result=InputSlurConstruction.Build(result,e,BitConverter.ToSingle(ds,0x8780),boundary,BitConverter.ToInt16(prefs,42),end);}int expectedCount=a.Length>5?BitConverter.ToInt16(File.ReadAllBytes(a[5]),0x8798):count+1;if(result.Count!=expectedCount)throw new Exception("Record count "+result.Count+" != "+expectedCount);int checks=0;for(int i=0;i<result.Count;i++)for(int p=0;p<15;p++){uint actual=BitConverter.ToUInt32(BitConverter.GetBytes(result[i][p]),0),want=BitConverter.ToUInt32(after,i*60+p*4);if(actual!=want)throw new Exception("Record "+i+" P"+(p+1)+" "+actual.ToString("x8")+" != "+want.ToString("x8")+" ("+result[i][p]+" vs "+BitConverter.ToSingle(after,i*60+p*4)+")");checks++;}Console.WriteLine("PASS "+checks+" original slur-construction record words.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}
